/* From Uiverse.io by vinodjangid07 - Tags: switch, hamburger */
.__UIV_SCOPE__ #checkbox {
  display: none;
}

.__UIV_SCOPE__ .toggle {
  position: relative;
  width: 40px;
  height: 40px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  transition-duration: .5s;
}

.__UIV_SCOPE__ .bars {
  width: 100%;
  height: 4px;
  background-color: rgb(176, 92, 255);
  border-radius: 4px;
}

.__UIV_SCOPE__ #bar2 {
  transition-duration: .8s;
}

.__UIV_SCOPE__ #bar1,.__UIV_SCOPE__ #bar3 {
  width: 70%;
}

.__UIV_SCOPE__ #checkbox:checked + .toggle .bars {
  position: absolute;
  transition-duration: .5s;
}

.__UIV_SCOPE__ #checkbox:checked + .toggle #bar2 {
  transform: scaleX(0);
  transition-duration: .5s;
}

.__UIV_SCOPE__ #checkbox:checked + .toggle #bar1 {
  width: 100%;
  transform: rotate(45deg);
  transition-duration: .5s;
}

.__UIV_SCOPE__ #checkbox:checked + .toggle #bar3 {
  width: 100%;
  transform: rotate(-45deg);
  transition-duration: .5s;
}

.__UIV_SCOPE__ #checkbox:checked + .toggle {
  transition-duration: .5s;
  transform: rotate(180deg);
}
